import {installPicoGPIO} from './pico-gpio-compat.js';
import {installPicoPWM} from './pico-pwm-compat.js';
import {installPicoUART} from './pico-uart-compat.js';
import {installRiscvIRQ} from './pico-riscv-sdk.js';
import {installPicoADC} from './pico-adc-fix.js';
import {installPicoDMA} from './pico-dma-fix.js';
import {PicoNVIC} from './pico-nvic.js';
import {defaultPicoEnvironment,picoEnvironment,sampleInternalADC} from './pico-environment.js';
import {PicoGPIOIRQ} from './pico-gpio-irq.js';
import {RP2040,RP2350,USBCDC} from './pico-engine.js';
import {PICO_BOARDS} from './pico-boards.js';
import {validatePicoImage,picoImageArchitecture} from './pico-image.js';
import {validateProject,componentDefinition,buildNets} from './core.js';
import {emptyProject} from './templates.js';
import {solveProjectDC,DC_FAILURES} from './dc-project.js';
import {ESPCircuitRuntime} from './esp-circuit-runtime.js';
import {PicoDebugger} from './pico-debugger.js';
import {PicoServices} from './pico-services.js';
import {PicoFlash} from './pico-flash.js';
import {PicoUSBHost} from './pico-usb-host.js';
import {CYW43Chip} from './pico-cyw43-chip.js';
export function solvePicoCircuit(project,pins={},drivers=[],reactive=null){const board=PICO_BOARDS[project.components.find(c=>c.type==='board')?.params.model];const result=solveProjectDC(project,{pins},buildNets(project),{board,pwmAverage:false,drivers,reactive});const fault=result.diagnostics.find(d=>DC_FAILURES.includes(d.code));return{...result,valid:result.valid&&!fault,fault};}
export class PicoCircuit extends ESPCircuitRuntime{
 state(){const r=this.runtime;if(this.lastGPIO===r.gpioVersion)return false;this.lastGPIO=r.gpioVersion;this.pins=r.pinStates();return true;}
 cycle(){return this.runtime.referenceCycles;}
 solve(){const drivers=[...this.drivers];for(const[p,s]of Object.entries(this.pins||{}))if(s.mode==='INPUT_PULLDOWN')drivers.push({endpoint:this.board.id+':'+p,voltage:0,ohms:30000});this.solution=solvePicoCircuit(this.project,this.pins||{},drivers,this.reactiveStamps);if(!this.solution.valid)throw Error(this.solution.fault?.message||'Pico devresi çözülemedi.');for(const pin of this.runtime.board.gpio){const id='GPIO'+pin,voltage=this.solution.voltages.get(this.solution.netlist.net(this.board.id+':'+id));if(Number.isFinite(voltage)&&(voltage>3.6||voltage<-.3))throw Error(id+' Pico 3.3 V GPIO sınırını aşıyor.');const high=Number.isFinite(voltage)?voltage>=2.31:this.pins?.[id]?.mode==='INPUT_PULLUP';this.runtime.inputs[id]=high;this.runtime.rp.gpio[pin].setInputValue(!!high);}}
}
export class PicoRuntime{
 constructor(image,id){this.environment=defaultPicoEnvironment();this.board=PICO_BOARDS[id];this.chip=id;this.image=validatePicoImage(image,id).slice();this.architecture=picoImageArchitecture(image);this.stackRegister=this.architecture==='riscv'?2:13;this.flashState=new Uint8Array(this.board.flashSize).fill(255);this.flashState.set(this.image);this.circuitDefinition=this.board;this.circuitValidate=p=>validateProject({...emptyProject(),...p,language:'c',firmware:undefined});this.circuitSolve=p=>solvePicoCircuit(p);this.partDefinition=componentDefinition;this.hz=this.board.hz;this.createCPU();}
 createCPU(){const newer=this.board.mcu==='RP2350',rp=this.rp=newer?new RP2350({coreArch:this.architecture}):new RP2040();rp.clkSys=rp.clkPeri=this.hz;rp.flash.set(this.flashState);this.flashService=new PicoFlash(this);this.core=rp.core[0];const v=new DataView(this.flashState.buffer),sp=v.getUint32(0,true);if(this.architecture==='riscv'){this.core.registerSet.setRegisterU(2,sp);}else if(newer){this.core.regs.sp=sp;this.core.regs.msp=sp;}else this.core.SP=sp;this.core.PC=v.getUint32(4,true)&~1;if(this.architecture!=='riscv')rp.writeUint32(0xe000ed08,0x10000000);this.count=0;this.referenceCycles=0;this.gpioVersion=0;this.inputs={};this.serial='';this.serialRXAt=0;installPicoADC(this);installPicoDMA(this);installPicoUART(this);installPicoPWM(this);installPicoGPIO(this);if(this.architecture==='riscv')installRiscvIRQ(this);this.nvic=this.architecture==='riscv'?{read:()=>null,write:()=>false}:new PicoNVIC(this);this.gpioIRQ=new PicoGPIOIRQ(this);this.services=new PicoServices(this);this.cyw43=this.board.wireless?new CYW43Chip({vbus:()=>this.environment.vbus,onPower:on=>{if(!on)this.services.command(0);},onLED:on=>{this.services.radio.led=on;}}):null;this.cyw43?.attach(rp);rp.usbCtrl.debug=()=>{};this.usbHost=new PicoUSBHost(rp.usbCtrl);this.usbHost.onSerialData=bytes=>{this.serial+=new TextDecoder().decode(bytes);};const write=rp.writeUint32.bind(rp);rp.writeUint32=(address,value)=>{if(!this.nvic.write(address,value)&&!this.gpioIRQ.write(address,value)&&!this.flashService.write(address,value)&&!this.services.write(address,value))write(address,value);};rp.uart[0].onByte=c=>this.serial+=String.fromCharCode(c);for(const g of rp.gpio)if(this.board.gpio.includes(g.index))g.addListener(()=>{this.gpioVersion++;this.circuit?.refresh();});const read=rp.readUint32.bind(rp);rp.readUint32=address=>{if((address>>>0)===0xd0000004)this.circuit?.refresh();return this.nvic.read(address)??this.gpioIRQ.read(address)??this.flashService.read(address)??this.services.read(address)??read(address);};this.lastADCError=null;this.adcErrorAlarm=rp.clock.createAlarm(()=>rp.adc.completeADCRead(0,true));const sample=rp.adc.onADCRead;rp.adc.onADCRead=channel=>{if(!sampleInternalADC(this,channel))return;if(channel<3&&this.circuit){this.circuit.refresh(true);const voltage=this.circuit.solution.voltages.get(this.circuit.solution.netlist.net(this.circuit.board.id+':GPIO'+(26+channel)));rp.adc.channelValues[channel]=Math.round(Math.max(0,Math.min(3.3,Number.isFinite(voltage)?voltage:0))/3.3*4095);}sample(channel);};rp.uart[1].onByte=c=>this.serial+=String.fromCharCode(c);this.emulator={cycles:()=>this.count};}
 configureEnvironment(config){this.environment=picoEnvironment(config);if(this.circuit)this.circuit.project.settings.picoEnvironment={...this.environment};}
 attachCircuit(project){this.configureEnvironment(project.settings?.picoEnvironment||{});if(project.settings?.picoNetwork)this.services.configureNetwork(project.settings.picoNetwork);this.circuit=new PicoCircuit(this,project);this.circuit.refresh(true);return this.circuit;}
 pinStates(){return Object.fromEntries(this.board.gpio.map(n=>{const p=this.rp.gpio[n],s=p.value,output=s===0||s===1;return['GPIO'+n,{high:output?s===1:!!this.inputs['GPIO'+n],outputEnabled:output,voltage:output?(s===1?3.3:0):null,mode:output?'OUTPUT':s===3?'INPUT_PULLUP':s===4?'INPUT_PULLDOWN':'INPUT'}];}));}
 setDebugInfo(info){this.debugger=new PicoDebugger(this,info);}
 step(count){for(let i=0;i<count;i++){if(this.flashService.bootsel||this.debugger?.shouldStop())break;const before=this.core.cycles;this.rp.currentCore=0;this.core.executeInstruction();const elapsed=this.core.cycles-before;if(elapsed<=0)throw Error('Pico CPU ilerlemedi.');if(this.services.core1){const c=this.rp.core[1];this.rp.currentCore=1;let budget=0;while(c.cycles<this.core.cycles&&budget++<64){const prev=c.cycles;c.executeInstruction();if(c.cycles<=prev)throw Error('Pico core 1 ilerlemedi.');}}this.rp.currentCore=0;this.rp.stepThings(elapsed);this.count=this.core.cycles;this.referenceCycles=this.rp.clock.nanos*.016;if(this.circuit?.clockEvents[0]?.at<=this.referenceCycles)this.circuit.refresh(true);if(this.debugger?.afterInstruction())break;}const out=this.serial;this.serial='';return out;}
 queueSerial(text){for(const c of new TextEncoder().encode(text)){if(this.usbHost.initialized&&this.usbHost.kind==='cdc'){this.usbHost.sendSerialByte(c);continue;}const u=this.rp.uart[0],now=this.rp.clock.nanos,at=Math.max(now,this.serialRXAt||0),baud=Number.isFinite(u.baudRate)&&u.baudRate>0?u.baudRate:115200,frame=1+u.wordLength+((u.lineCtrlRegister&2)?1:0)+((u.lineCtrlRegister&8)?2:1);this.serialRXAt=at+frame*1e9/baud;this.rp.clock.createAlarm(()=>u.feedByte(c)).schedule(at-now);}}
 registers(){if(this.architecture==='riscv')return Array.from({length:32},(_,i)=>this.core.registerSet.getRegisterU(i));return Array.from(this.board.mcu==='RP2350'?this.core.regs.r:this.core.registers);}
 reset(){const project=this.circuit?.project,rom=this.cyw43?.rom;this.circuit?.peripherals?.dispose();this.circuit=null;this.cyw43?.dispose();this.createCPU();if(rom)this.cyw43?.loadROM(rom);if(project)this.attachCircuit(project);}
 dispose(){this.cyw43?.dispose();this.circuit?.peripherals?.dispose();this.circuit=null;this.rp=null;this.core=null;}
}
